 const data=new Map<string,string>(),repo=new Repository(persistent?privateStore:{read:async k=>data.get(k)??null,write:async(k,v)=>{data.set(k,v);},remove:async k=>{data.delete(k);}});const prior=await repo.loadProfile();if(!prior.name&&!prior.studentId&&!prior.className)await repo.saveProfile({name:'原姓名',studentId:'0001',className:'A班'});
 const exp={id:'abcdef123456',sourceId:'测试',name:'学生信息识别核对',category:'mechanics',schema:{groups:[{name:'数据',fields:[{key:'v',label:'测量值',type:'number',required:true}]}]}} as Experiment;
